oxy_webhelp_navlinks = {"aws_deployment_models_cloud_acc-d39307e15749":{"topics":[{"title":"Setup flow by deployment model","shortdesc":"<p class=\"shortdesc\">After you choose a deployment model for an AWS cloud account, follow the setup phases         for that model.<\/p>","href":"saas\/aws_deployment_model_setup_flow.html","attributes":{"data-id":"aws_deployment_model_setup_flow"},"menu":{"hasChildren":false},"tocID":"aws_deployment_model_setup_flow-d39307e15766","topics":[]},{"title":"Customer-controlled storage and keys","shortdesc":"<p class=\"shortdesc\">You can archive the backups of an <span class=\"ph\">RSC<\/span>-managed AWS account to a         customer-controlled archival location and encrypt them with your own AWS Key Management         Service key.<\/p>","href":"saas\/aws_cust_controlled_storage.html","attributes":{"data-id":"aws_cust_controlled_storage"},"menu":{"hasChildren":false},"tocID":"aws_cust_controlled_storage-d39307e15777","topics":[]},{"title":"<span class=\"ph\">RSC<\/span>-managed IaaS workloads","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provisions and manages the AWS resources required to back up         Infrastructure as a Service (IaaS) workload hosts on your behalf, and uses AWS Systems         Manager to install the Rubrik Backup Service on the hosts, when you use an <span class=\"ph\">RSC<\/span>-managed deployment.<\/p>","href":"saas\/cces_rsc_managed_iaas_workloads.html","attributes":{"data-id":"cces_rsc_managed_iaas_workloads"},"menu":{"hasChildren":false},"tocID":"cces_rsc_managed_iaas_workloads-d39307e15791","topics":[]}]}};